import{_ as p,a0 as o,w as l,s as h,I as s,x as t,a1 as i,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux 平台下 Python 腳本編程入門（一） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 平台下 Python 腳本編程入門（一） | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 平台下 Python 腳本編程入門（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 平台下 Python 腳本編程入門（一） | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160525 Getting Started with Python Programming and Scripting in Linux – Part 1","title":"Linux 平台下 Python 腳本編程入門（一）","tag":"201608","desc":""},"relativePath":"201608/20160525 Getting Started with Python Programming and Scripting in Linux – Part 1.md","filePath":"[post].md"}'),r={name:"201608/20160525 Getting Started with Python Programming and Scripting in Linux – Part 1.md"};function g(u,n,c,y,m,k){const a=o("Link");return l(),h("div",null,[n[21]||(n[21]=s("h1",{id:"linux-平台下-python-腳本編程入門-一",tabindex:"-1"},[t("Linux 平台下 Python 腳本編程入門（一） "),s("a",{class:"header-anchor",href:"#linux-平台下-python-腳本編程入門-一","aria-label":"Permalink to “Linux 平台下 Python 腳本編程入門（一）”"},"​")],-1)),n[22]||(n[22]=s("p",null,"眾所周知，系統管理員需要精通一門腳本語言，而且招聘機構列出的職位需求上也會這麼寫。大多數人會認為 Bash （或者其他的 shell 語言）用起來很方便，但一些強大的語言（比如 Python）會給你帶來一些其它的好處。",-1)),n[23]||(n[23]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2016/05/Learn-Python-Programming-Scripting-in-Linux.png",alt:""})],-1)),n[24]||(n[24]=s("p",null,[s("em",null,"在 Linux 中學習 Python 腳本編程")],-1)),n[25]||(n[25]=s("p",null,"首先，我們會使用 Python 的命令列工具，還會接觸到 Python 的面向對象特性（這篇文章的後半部分會談到它）。",-1)),s("p",null,[n[2]||(n[2]=t("學習 Python 可以助力於你在",-1)),i(a,{href:"http://www.tecmint.com/create-gui-applications-in-linux/"},{default:e(()=>[...n[0]||(n[0]=[t("桌面應用開發",-1)])]),_:1}),n[3]||(n[3]=t("及",-1)),i(a,{href:"http://www.datasciencecentral.com/profiles/blogs/the-guide-to-learning-python-for-data-science-2"},{default:e(()=>[...n[1]||(n[1]=[t("數據科學領域",-1)])]),_:1}),n[4]||(n[4]=t("的職業發展。",-1))]),n[26]||(n[26]=d(`<p>容易上手，廣泛使用，擁有海量“開箱即用”的模組（它是一組包含 Python 語句的外部文件），Python 理所當然地成為了美國計算機專業大學生在一年級時所上的程序設計課所用語言的不二之選。</p><p>在這個由兩篇文章構成的系列中，我們將回顧 Python 的基礎部分，希望初學編程的你能夠將這篇實用的文章作為一個編程入門的跳板，和日後使用 Python 時的一篇快速指引。</p><h3 id="linux-中的-python" tabindex="-1">Linux 中的 Python <a class="header-anchor" href="#linux-中的-python" aria-label="Permalink to “Linux 中的 Python”">​</a></h3><p>Python 2.x 和 3.x 通常已經內置在現代 Linux 發行版中，你可以立刻使用它。你可以終端模擬器中輸入 <code>python</code> 或 <code>python3</code> 來進入 Python shell, 並輸入 <code>quit()</code> 退出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ which python</span></span>
<span class="line"><span>$ which python3</span></span>
<span class="line"><span>$ python -v</span></span>
<span class="line"><span>$ python3 -v</span></span>
<span class="line"><span>$ python</span></span>
<span class="line"><span>&gt;&gt;&gt; quit()</span></span>
<span class="line"><span>$ python3</span></span>
<span class="line"><span>&gt;&gt;&gt; quit()</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Running-Python-Commands-on-Linux.png" alt=""></p><p><em>在 Linux 中運行 Python 命令</em></p><p>如果你希望在鍵入 <code>python</code> 時使用 Python 3.x 而不是 2.x，你可以像下面一樣更改對應的符號鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm /usr/bin/python </span></span>
<span class="line"><span>$ cd /usr/bin</span></span>
<span class="line"><span>$ ln -s python3.2 python # Choose the Python 3.x binary here</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Remove-Python-2-and-Use-Python-3.png" alt=""></p><p><em>刪除 Python 2，使用 Python 3</em></p><p>順便一提，有一點需要注意：儘管 Python 2.x 仍舊被使用，但它並不會被積極維護。因此，你可能要考慮像上面指示的那樣來切換到 3.x。2.x 和 3.x 的語法有一些不同，我們會在這個系列文章中使用後者。</p><p>另一個在 Linux 中使用 Python 的方法是通過 IDLE (the Python Integrated Development Environment)，這是一個為編寫 Python 代碼而生的圖形用户界面。在安裝它之前，你最好查看一下適用於你的 Linux 發行版的 IDLE 可用版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># aptitude search idle     [Debian 及其衍生發行版]</span></span>
<span class="line"><span># yum search idle          [CentOS 和 Fedora]</span></span>
<span class="line"><span># dnf search idle          [Fedora 23+ 版本]</span></span></code></pre></div><p>然後，你可以像下面一樣安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo aptitude install idle-python3.2    # I&#39;m using Linux Mint 13</span></span></code></pre></div><p>安裝成功後，你會看到 IDLE 的運行畫面。它很像 Python shell，但是你可以用它做更多 Python shell 做不了的事。</p><p>比如，你可以:</p><ol><li><p>輕鬆打開外部文件 (File → Open)；</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Python-Shell.png" alt=""></p><p><em>Python Shell</em></p></li><li><p>複製 (<code>Ctrl + C</code>) 和粘貼 (<code>Ctrl + V</code>) 文本；</p></li><li><p>查找和替換文本；</p></li><li><p>顯示可能的代碼補全（一個在其他 IDE 裏可能叫做“智能感知”或者“自動補完”的功能）；</p></li><li><p>更改字體和字號，等等。</p></li></ol><p>最厲害的是，你可以用 IDLE 創建桌面應用。</p><p>我們在這兩篇文章中不會開發桌面應用，所以你可以根據喜好來選擇 IDLE 或 Python shell 去運行下面的例子。</p><h3 id="python-中的基本運算" tabindex="-1">Python 中的基本運算 <a class="header-anchor" href="#python-中的基本運算" aria-label="Permalink to “Python 中的基本運算”">​</a></h3><p>就像你預料的那樣，你能夠直接進行算術操作（你可以在你的所有運算中使用足夠多的括號！），還可以輕鬆地使用 Python 拼接字符串。</p><p>你還可以將運算結果賦給一個變量，然後在屏幕上顯示它。Python 有一個叫做拼接 (concatenation) 的實用功能——給 print 函數提供一串用逗號分隔的變量和/或字符串，它會返回一個由你剛才提供的變量依序構成的句子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; a = 5</span></span>
<span class="line"><span>&gt;&gt;&gt; b = 8</span></span>
<span class="line"><span>&gt;&gt;&gt; x = b / a</span></span>
<span class="line"><span>&gt;&gt;&gt; x</span></span>
<span class="line"><span>1.6</span></span>
<span class="line"><span>&gt;&gt;&gt; print(b, &quot;divided by&quot;, a, &quot;equals&quot;, x)</span></span></code></pre></div><p>注意，你可以將不同類型的變量（數字，字符串，布爾符號等等）混合在一起。當你將一個值賦給一個變量後，你可以隨後更改它的類型，不會有任何問題（因此，Python 被稱為動態類型語言）。</p><p>如果你嘗試在靜態類型語言中（如 Java 或 C#）做這件事，它將拋出一個錯誤。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Learn-Python-Basic-Operations.png" alt=""></p><p><em>學習 Python 的基本操作</em></p><h3 id="面向對象編程的簡單介紹" tabindex="-1">面向對象編程的簡單介紹 <a class="header-anchor" href="#面向對象編程的簡單介紹" aria-label="Permalink to “面向對象編程的簡單介紹”">​</a></h3><p>在面向對象編程（OOP）中，程序中的所有實體都會由對象的形式呈現，並且它們可以與其他對象交互。因此，對象擁有屬性，而且大多數對象可以執行動作（這被稱為對象的方法）。</p><p>舉個例子：我們來想像一下，創建一個對象“狗”。它可能擁有的一些屬性有<code>顏色</code>、<code>品種</code>、<code>年齡</code>等等，而它可以完成的動作有 <code>叫()</code>、<code>吃()</code>、<code>睡覺()</code>，諸如此類。</p><p>你可以看到，方法名後面會跟着一對括號，括號當中可能會包含一個或多個參數（向方法中傳遞的值），也有可能什麼都不包含。</p><p>我們用 Python 的基本對象類型之一——列表來解釋這些概念。</p><h3 id="解釋對象的屬性和方法-python-中的列表" tabindex="-1">解釋對象的屬性和方法：Python 中的列表 <a class="header-anchor" href="#解釋對象的屬性和方法-python-中的列表" aria-label="Permalink to “解釋對象的屬性和方法：Python 中的列表”">​</a></h3><p>列表是條目的有序組合，而這些條目所屬的數據類型並不需要相同。我們像下面一樣來使用一對方括號，來創建一個名叫 <code>rockBands</code> 的列表：</p><p>你可以向 <code>rockBands</code> 的 <code>append()</code> 方法傳遞條目，來將它添加到列表的尾部，就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands = []</span></span>
<span class="line"><span>&gt;&gt;&gt; rockBands.append(&quot;The Beatles&quot;)</span></span>
<span class="line"><span>&gt;&gt;&gt; rockBands.append(&quot;Pink Floyd&quot;)</span></span>
<span class="line"><span>&gt;&gt;&gt; rockBands.append(&quot;The Rolling Stones&quot;)</span></span></code></pre></div><p>為了從列表中移除元素，我們可以向 <code>remove()</code> 方法傳遞特定元素，或向 <code>pop()</code> 中傳遞列表中待刪除元素的位置（從 0 開始計數）。</p><p>換句話説，我們可以用下面這種方法來從列表中刪除 “The Beatles”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands.remove(&quot;The Beatles&quot;)</span></span></code></pre></div><p>或者用這種方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands.pop(0)</span></span></code></pre></div><p>如果你輸入了對象的名字，然後在後面輸入了一個點，你可以按 <code>Ctrl + space</code> 來顯示這個對象的可用方法列表。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/List-Available-Python-Methods.png" alt=""></p><p><em>列出可用的 Python 方法</em></p><p>列表中含有的元素個數是它的一個屬性。它通常被叫做“長度”，你可以通過向內建函數 <code>len</code> 傳遞一個列表作為它的參數來顯示該列表的長度（順便一提，之前的例子中提到的 print 語句，是 Python 的另一個內建函數）。</p><p>如果你在 IDLE 中輸入 <code>len</code>，然後跟上一個不閉合的括號，你會看到這個函數的默認語法：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/05/Python-len-Function.png" alt=""></p><p><em>Python 的 len 函數</em></p><p>現在我們來看看列表中的特定條目。它們也有屬性和方法嗎？答案是肯定的。比如，你可以將一個字符串條目轉換為大寫形式，並獲取這個字符串所包含的字符數量。像下面這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; rockBands[0].upper()</span></span>
<span class="line"><span>&#39;THE BEATLES&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; len(rockBands[0])</span></span>
<span class="line"><span>11</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇文章中，我們簡要介紹了 Python、它的命令列 shell、IDLE，展示瞭如何執行算術運算，如何在變量中存儲數據，如何使用 <code>print</code> 函數在屏幕上重新顯示那些數據（無論是它們本身還是它們的一部分），還通過一個實際的例子解釋了對象的屬性和方法。</p><p>下一篇文章中，我們會展示如何使用條件語句和循環語句來實現流程控制。我們也會解釋如何編寫一個腳本來幫助我們完成系統管理任務。</p>`,55)),s("p",null,[n[6]||(n[6]=t("你是不是想繼續學習一些有關 Python 的知識呢？敬請期待本系列的第二部分（我們會在腳本中將 Python 和命令列工具的優點結合在一起），你還可以考慮購買我們的《終極 Python 編程》系列教程（",-1)),i(a,{href:"http://www.tecmint.com/learn-python-programming-online-with-ultimate-python-coding/"},{default:e(()=>[...n[5]||(n[5]=[t("這裏",-1)])]),_:1}),n[7]||(n[7]=t("有詳細信息）。",-1))]),n[27]||(n[27]=s("p",null,"像往常一樣，如果你對這篇文章有什麼問題，可以向我們尋求幫助。你可以使用下面的聯繫表單向我們發送留言，我們會盡快回復你。",-1)),n[28]||(n[28]=s("hr",null,null,-1)),s("p",null,[n[9]||(n[9]=t("via: ",-1)),i(a,{href:"http://www.tecmint.com/learn-python-programming-and-scripting-in-linux/"},{default:e(()=>[...n[8]||(n[8]=[t("http://www.tecmint.com/learn-python-programming-and-scripting-in-linux/",-1)])]),_:1})]),s("p",null,[n[13]||(n[13]=t("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:e(()=>[...n[10]||(n[10]=[t("Gabriel Cánepa",-1)])]),_:1}),n[14]||(n[14]=t(" 譯者：",-1)),i(a,{href:"https://github.com/StdioA"},{default:e(()=>[...n[11]||(n[11]=[t("StdioA",-1)])]),_:1}),n[15]||(n[15]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[12]||(n[12]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[18]||(n[18]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[16]||(n[16]=[t("LCTT",-1)])]),_:1}),n[19]||(n[19]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...n[17]||(n[17]=[t("Linux中國",-1)])]),_:1}),n[20]||(n[20]=t(" 榮譽推出",-1))])])}const f=p(r,[["render",g]]);export{x as __pageData,f as default};
